#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals euclidean_geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Theorem circles_equilateral_tangent_sum : exists (m n : nat), coprime m n /\ let rA := 10%:R in let rB := 3%:R in let rC := 2%:R in let rD := 2%:R in let rE := (m%:R) / (n%:R) in exists (O : 'rV[R]_2) (EA EB EC ED : 'rV[R]_2), exists (VA VB VC : 'rV[R]_2), [/\ norm (VA - O) = rA, norm (VB - O) = rA, norm (VC - O) = rA, norm (VB - VA) = norm (VC - VB), norm (VC - VB) = norm (VA - VC), norm (EA - VA) = rB + rA, norm (EB - VB) = rC + rA, norm (EC - VC) = rD + rA, norm (ED - VC) = rE + rA].
